#!/usr/bin/env python3
import sys, os, re, json, time, tempfile, subprocess, shlex
from dataclasses import dataclass

RESET = "\033[0m"
VALID_GROUPS = ["numbers", "urls", "pointers", "dates", "paths", "quotes", "key-value-pairs", "uuids", "ip-addresses", "processes", "json"]
VALID_COLORS = {"red":"31", "green":"32", "yellow":"33", "blue":"34", "magenta":"35", "cyan":"36"}


def c(text, code):
    if text == "":
        return f"\033[{code}m{RESET}"
    return f"\033[{code}m{text}{RESET}"

@dataclass
class Span:
    start: int
    end: int
    code: str = None
    repl: str = None

class Styler:
    def __init__(self, s):
        self.s = s
        self.occ = [False] * len(s)
        self.spans = []
    def free(self, a, b):
        if a < 0 or b > len(self.s) or a >= b:
            return False
        return not any(self.occ[a:b])
    def add(self, a, b, code=None, repl=None):
        if not self.free(a,b):
            return False
        for i in range(a,b): self.occ[i] = True
        self.spans.append(Span(a,b,code,repl))
        return True
    def add_force(self, a, b, code=None, repl=None):
        if a >= b: return False
        for i in range(a,b): self.occ[i] = True
        self.spans.append(Span(a,b,code,repl))
        return True
    def render(self):
        out=[]; pos=0
        for sp in sorted(self.spans, key=lambda x:(x.start,x.end)):
            if sp.start < pos:
                continue
            out.append(self.s[pos:sp.start])
            if sp.repl is not None:
                out.append(sp.repl)
            elif sp.code is not None:
                out.append(c(self.s[sp.start:sp.end], sp.code))
            else:
                out.append(self.s[sp.start:sp.end])
            pos=sp.end
        out.append(self.s[pos:])
        return ''.join(out)

