        self.occ = [False] * len(s)
        self.spans = []
    def free(self, a, b):
        if a < 0 or b > len(self.s) or a >= b:
            return False
        return not any(self.occ[a:b])
    def add(self, a, b, code=None, repl=None):
        if not self.free(a,b):
            return False
        for i in range(a,b): self.occ[i] = True
        self.spans.append(Span(a,b,code,repl))
        return True
    def add_force(self, a, b, code=None, repl=None):
        if a >= b: return False
        for i in range(a,b): self.occ[i] = True
        self.spans.append(Span(a,b,code,repl))
        return True
