def die2(msg, prog="executable", tip=False):
    if tip:
        sys.stderr.write(f"error: unexpected argument '{msg}' found\n\n  tip: to pass '{msg}' as a value, use '-- {msg}'\n\nUsage: {prog} [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n")
    else:
        sys.stderr.write(msg)
    sys.exit(2)

def clap_unexpected(arg, prog):
    if arg.startswith('--'):
