    sys.exit(2)

def missing_value(opt, metav=None):
    if metav:
        sys.stderr.write(f"error: a value is required for '{opt} <{metav}>' but none was supplied\n")
        if opt in ('--enable','--disable'):
            sys.stderr.write("  [possible values: numbers, urls, pointers, dates, paths, quotes, key-value-pairs, uuids, ip-addresses, processes, json]\n")
        sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(2)

def parse_args(argv):
    prog = os.path.basename(argv[0]) or "executable"
    opts = {"follow":False, "print":False, "config":None, "exec":None, "highlights":[], "enable":[], "disable":[], "disable_builtin":False, "pager":None, "file":None}
    args = argv[1:]
    i=0; after_dd=False
    def take_value(name, meta, curval=None):
        nonlocal i
        if curval is not None:
            return curval
        if i+1 >= len(args):
            missing_value(name, meta)
        i += 1
