        a=args[i]
        if after_dd:
            if opts["file"] is None: opts["file"] = a
            else: clap_unexpected(a, prog)
            i+=1; continue
        if a == '--':
            after_dd=True; i+=1; continue
        if a == '--help': print(help_text(True, prog), end=''); sys.exit(0)
        if a == '-h': print(help_text(False, prog), end=''); sys.exit(0)
        if a == '--version' or a == '-V': print('tspin 5.6.0'); sys.exit(0)
        if a.startswith('--'):
            name,val=(a.split('=',1)+[None])[:2] if '=' in a else (a,None)
            if name in ('--follow',): opts['follow']=True
            elif name in ('--print',): opts['print']=True
            elif name == '--disable-builtin-keywords': opts['disable_builtin']=True
            elif name == '--config-path': opts['config']=take_value(name,'CONFIG_PATH',val)
            elif name == '--exec': opts['exec']=take_value(name,'EXEC',val)
            elif name == '--pager': opts['pager']=take_value(name,'PAGER',val)
            elif name == '--highlight': opts['highlights'].append(take_value(name,'COLOR_WORD',val))
            elif name == '--enable': opts['enable'].append(take_value(name,'ENABLED_HIGHLIGHTERS',val))
            elif name == '--disable': opts['disable'].append(take_value(name,'DISABLED_HIGHLIGHTERS',val))
            else: clap_unexpected(a, prog)
            i+=1; continue
        if a.startswith('-') and a != '-':
            # grouped short flags; -e may take the remainder as its value
            j=1
            while j < len(a):
                ch=a[j]
                if ch == 'f': opts['follow']=True; j+=1
                elif ch == 'p': opts['print']=True; j+=1
                elif ch == 'h': print(help_text(False, prog), end=''); sys.exit(0)
                elif ch == 'V': print('tspin 5.6.0'); sys.exit(0)
                elif ch == 'e':
                    if j+1 < len(a): opts['exec']=a[j+1:]; j=len(a)
