    opts['enable'] = validate_group_list(opts['enable'], '--enable', 'ENABLED_HIGHLIGHTERS')
    opts['disable'] = validate_group_list(opts['disable'], '--disable', 'DISABLED_HIGHLIGHTERS')
    h=[]
